//! Vorbis codebook headers: codeword-length tables and the VQ lookup table.
//!
//! A codebook is the entropy coder plus an optional vector quantizer. This file
//! parses and stores both; the Huffman tree itself is built in the decode stage,
//! because `open` does not produce PCM yet.
//!
//! Lookup type 1 is the interesting one: it stores only `lookup_values` scalars,
//! from which every `dimensions`-element VQ vector is generated by a lattice
//! index. `latticeIndex` documents that mapping so the next stage has it in one
//! place. Lookup type 2 stores `entries * dimensions` scalars explicitly.

const std = @import("std");
const types = @import("types.zig");
const vorbis_bits = @import("vorbis_bits.zig");

const BitReader = vorbis_bits.BitReader;
const ilog = vorbis_bits.ilog;
const lookup1Values = vorbis_bits.lookup1Values;

pub const Error = types.Error;

/// Engineering caps. The container format allows 2^16 dimensions and 2^24
/// entries; those would make one setup header larger than any real file.
pub const max_dimensions: usize = 4096;
pub const max_entries: usize = 1 << 16;
pub const max_multiplicands: usize = 1 << 21;

pub const Codebook = struct {
    dimensions: u16 = 0,
    entries: u32 = 0,
    ordered: bool = false,
    /// One codeword length per entry, 1..32; 0 marks a sparse unused entry.
    lengths: []u8 = &.{},
    lookup_type: u4 = 0,
    minimum_value: f32 = 0,
    delta_value: f32 = 0,
    /// Width of each scalar in `multiplicands` (1..16).
    value_bits: u5 = 0,
    sequence_p: bool = false,
    /// Number of scalars in `multiplicands`; also the lattice base for type 1.
    lookup_values: u32 = 0,
    multiplicands: []u16 = &.{},

    pub fn deinit(self: *Codebook, allocator: std.mem.Allocator) void {
        if (self.lengths.len != 0) allocator.free(self.lengths);
        if (self.multiplicands.len != 0) allocator.free(self.multiplicands);
        self.* = .{};
    }

    /// Lattice index of scalar `dimension` of VQ entry `offset`, per the Vorbis
    /// I specification's "Vector value decode: Lookup type 1":
    ///
    ///     multiplicand_offset = (offset / lookup_values^dimension) % lookup_values
    ///
    /// Every vector is rebuilt from the same `lookup_values` scalars, which is
    /// why a type 1 book is tiny compared to the equivalent type 2 table.
    pub fn latticeIndex(self: Codebook, offset: u32, dimension: u16) u32 {
        if (self.lookup_values == 0) return 0;
        var divisor: u64 = 1;
        var i: u16 = 0;
        while (i < dimension) : (i += 1) {
            divisor *= self.lookup_values;
            // Once the divisor passes the entry offset, every further power of
            // lookup_values also divides it to zero; bail out before the u64
            // product could overflow for an absurd dimensions value.
            if (divisor > offset) return 0;
        }
        return @intCast((@as(u64, offset) / divisor) % self.lookup_values);
    }
};

pub fn parse(allocator: std.mem.Allocator, bits: *BitReader) Error!Codebook {
    const sync = try bits.readBits(24);
    if (sync != 0x564342) return error.Corrupt;

    const dimensions_raw = try bits.readBits(16);
    if (dimensions_raw == 0 or dimensions_raw > max_dimensions) return error.Corrupt;
    const dimensions: u16 = @intCast(dimensions_raw);

    const entries = try bits.readBits(24);
    if (entries == 0 or entries > max_entries) return error.Corrupt;

    const lengths = try allocator.alloc(u8, entries);
    errdefer allocator.free(lengths);
    @memset(lengths, 0);

    const ordered = (try bits.readBit()) != 0;
    if (ordered) {
        // Runs of equal lengths, read as ilog(entries - current_entry)-bit
        // counts. A zero-length run is legal and just advances the length.
        var current_entry: u32 = 0;
        var current_length: u32 = (try bits.readBits(5)) + 1;
        while (current_entry < entries) {
            const left = entries - current_entry;
            const number = try bits.readBits(ilog(left));
            if (number > left) return error.Corrupt;
            if (number != 0) {
                @memset(lengths[current_entry..][0..@intCast(number)], @intCast(current_length));
            }
            current_entry += number;
            if (current_entry >= entries) break;
            current_length += 1;
            if (current_length > 32) return error.Corrupt;
        }
    } else {
        const sparse = (try bits.readBit()) != 0;
        for (lengths) |*slot| {
            if (sparse and (try bits.readBit()) == 0) continue;
            slot.* = @intCast((try bits.readBits(5)) + 1);
        }
    }

    const lookup_type: u4 = @intCast(try bits.readBits(4));
    if (lookup_type > 2) return error.Corrupt;

    var minimum_value: f32 = 0;
    var delta_value: f32 = 0;
    var value_bits: u5 = 0;
    var sequence_p = false;
    var lookup_values: u32 = 0;
    var multiplicands: []u16 = &.{};
    errdefer if (multiplicands.len != 0) allocator.free(multiplicands);

    if (lookup_type != 0) {
        minimum_value = try bits.readF32();
        delta_value = try bits.readF32();
        value_bits = @intCast((try bits.readBits(4)) + 1);
        sequence_p = (try bits.readBit()) != 0;

        const count: u64 = if (lookup_type == 1)
            lookup1Values(entries, dimensions)
        else
            @as(u64, entries) * dimensions;
        if (count > max_multiplicands) return error.Corrupt;
        lookup_values = @intCast(count);
        multiplicands = try allocator.alloc(u16, lookup_values);
        for (multiplicands) |*slot| slot.* = @intCast(try bits.readBits(value_bits));
    }

    return .{
        .dimensions = dimensions,
        .entries = entries,
        .ordered = ordered,
        .lengths = lengths,
        .lookup_type = lookup_type,
        .minimum_value = minimum_value,
        .delta_value = delta_value,
        .value_bits = value_bits,
        .sequence_p = sequence_p,
        .lookup_values = lookup_values,
        .multiplicands = multiplicands,
    };
}
